// Maps manifest. Greybox maps are generated by tools/gen-greybox-maps.ts (ASSETS §2.1).
import type { StructurePlacement } from './structures.ts';

export interface MapDef {
  readonly id: string;
  /** i18n key of the map name */
  readonly nameKey: string;
  /** px */
  readonly width: number;
  /** px */
  readonly height: number;
  /** URL of the mask PNG, relative to the site root */
  readonly maskUrl: string;
  /** px: spawn columns per team, in play order */
  readonly spawns: readonly (readonly number[])[];
  /** structures with HP (GDD §4.7): masonry and timber of the mask inside each rectangle */
  readonly structures?: readonly StructurePlacement[];
}

